namespace {uint32_t rd32(const uint8_t*p){return uint32_t(p[0])|uint32_t(p[1])<<8|uint32_t(p[2])<<16|uint32_t(p[3])<<24;}uint64_t rd64(const uint8_t*p){return rd32(p)|uint64_t(rd32(p+4))<<32;}}
void FPSNativeClient::_bind_methods(){ClassDB::bind_method(D_METHOD("connect_host","address","port"),&FPSNativeClient::connect_host);ClassDB::bind_method(D_METHOD("poll"),&FPSNativeClient::poll);ClassDB::bind_method(D_METHOD("send_control","type","data"),&FPSNativeClient::send_control);ClassDB::bind_method(D_METHOD("send_bytes","type","bytes","channel","reliable"),&FPSNativeClient::send_bytes,DEFVAL(0),DEFVAL(true));ClassDB::bind_method(D_METHOD("scene_peer"),&FPSNativeClient::scene_peer);ClassDB::bind_method(D_METHOD("activate","id"),&FPSNativeClient::activate);ClassDB::bind_method(D_METHOD("close"),&FPSNativeClient::close);}
Error FPSNativeClient::connect_host(const String&address,int port){close();if(port<1024||port>65535||!address.is_valid_ip_address())return ERR_INVALID_PARAMETER;host_.instantiate();Error e=host_->create_host(1,4);if(e!=OK){close();return e;}remote_=host_->connect_to_host(address,port,4);if(remote_.is_null()){close();return ERR_CANT_CONNECT;}scene_peer_.instantiate();assembly_=received_=-1;return OK;}
void FPSNativeClient::close(){if(remote_.is_valid()&&remote_->is_active())remote_->peer_disconnect_now();remote_.unref();if(host_.is_valid())host_->destroy();host_.unref();if(scene_peer_.is_valid())scene_peer_->_close();scene_peer_.unref();parts_.clear();}
Error FPSNativeClient::send_bytes(int type,const PackedByteArray&data,int channel,bool reliable){if(remote_.is_null()||!remote_->is_active()||type<1||type>int(cqwire::Type::AVATARS)||data.size()>65536||channel<0||channel>3)return ERR_INVALID_PARAMETER;PackedByteArray bytes;auto header=cqwire::packet(cqwire::Type(type));bytes.resize(header.size()+data.size());std::memcpy(bytes.ptrw(),header.data(),header.size());if(data.size())std::memcpy(bytes.ptrw()+header.size(),data.ptr(),data.size());Error result=remote_->send(channel,bytes,reliable?1:8);host_->flush();return result;}
Error FPSNativeClient::send_control(int type,const Dictionary&data){return send_bytes(type,JSON::stringify(data).to_utf8_buffer(),0,true);}
Array FPSNativeClient::decode(const PackedByteArray&b){Array out;if(!cqwire::header(b.ptr(),b.size()))return out;auto type=cqwire::type(b.ptr());auto payload=b.slice(cqwire::HEADER);Dictionary event;event["type"]=int(type);
 if(type==cqwire::Type::FRAME){if(payload.size()<36)return out;auto*p=payload.ptr();int64_t tick=int64_t(rd64(p));uint32_t raw=rd32(p+8),packed=rd32(p+12),index=rd32(p+16),count=rd32(p+20),epoch=rd32(p+32);uint64_t bits=rd64(p+24);double origin;std::memcpy(&origin,&bits,8);
  if(tick<0||tick<=received_||tick<assembly_||raw<14||raw>cqwire::MAX_FRAME||!packed||packed>cqwire::MAX_FRAME||!count||count>32||index>=count||count!=(packed+cqwire::CHUNK-1)/cqwire::CHUNK||!std::isfinite(origin)||payload.size()-36!=std::min(size_t(cqwire::CHUNK),size_t(packed)-index*cqwire::CHUNK))return out;
  if(tick!=assembly_){assembly_=tick;parts_.assign(count,{});raw_size_=raw;packed_size_=packed;epoch_=epoch;origin_=origin;parts_received_=0;}
  if(parts_.size()!=count||raw_size_!=raw||packed_size_!=packed||epoch_!=epoch||origin_!=origin||!parts_[index].is_empty())return out;parts_[index]=payload.slice(36);++parts_received_;if(parts_received_!=count)return out;PackedByteArray compressed;for(auto&part:parts_)compressed.append_array(part);auto frame=compressed.decompress(raw,FileAccess::COMPRESSION_FASTLZ);if(frame.size()!=raw||frame.size()<14||frame.slice(0,4).get_string_from_ascii()!="CQA3"||rd64(frame.ptr()+4)!=uint64_t(tick))return out;received_=tick;event["bytes"]=frame;event["tick"]=tick;event["epoch"]=epoch;event["origin"]=origin;
 }else if(type==cqwire::Type::ASSET_CHUNK||type==cqwire::Type::VOICE){event["bytes"]=payload;}else{if(payload.size()>cqwire::MAX_CONTROL)return out;Ref<JSON>parser;parser.instantiate();if(parser->parse(payload.get_string_from_utf8())!=OK||parser->get_data().get_type()!=Variant::DICTIONARY)return out;event["data"]=parser->get_data();}out.push_back(event);return out;
}
Array FPSNativeClient::poll(){Array events;if(host_.is_null())return events;for(int i=0;i<512;++i){Array e=host_->service(0);if(e.is_empty())break;int kind=e[0];if(kind==0)break;if(kind==1){Dictionary event;event["type"]=0;event["connected"]=true;events.push_back(event);}else if(kind==2){Dictionary event;event["type"]=-1;events.push_back(event);}else if(kind==3){auto packet=remote_->get_packet();if(packet.size()<=65544)events.append_array(decode(packet));}else if(kind<0)break;}return events;}
